  // Privacy policy page
  'priv.title': 'ప్రైవసీ పాలసీ',
  'priv.subtitle': 'మీ ప్రైవసీ సంపూర్ణం - మేము ఏమీ సేకరించము',
  'priv.updated': 'చివరిసారి అప్‌డేట్ చేసింది: డిసెంబర్ 2024',
  'priv.zero.title': 'సున్నా డేటా సేకరణ విధానం',
  'priv.zero.body': 'OpenAlgo, OpenAlgo వెబ్ పోర్టల్ ఏ విధమైన వినియోగదారు డేటాను సేకరించవు, నిల్వ చేయవు, ప్రసారం చేయవు, ప్రాసెస్ చేయవు. అనలిటిక్స్ లేదు, టెలిమెట్రీ లేదు, ట్రాకింగ్ కుకీలు లేవు, వినియోగదారు ప్రవర్తన మానిటరింగ్ లేదు, ఎలాంటి డేటా సేకరణ లేదు.',
  'priv.dont.title': 'మేము ఏమి సేకరించము',
  'priv.dont.i1l': 'వ్యక్తిగత సమాచారం లేదు:',
  'priv.dont.i1d': 'మేము పేర్లు, ఇమెయిల్స్, లేదా గుర్తింపు సమాచారం ఏదీ సేకరించము',
  'priv.dont.i2l': 'వినియోగ డేటా లేదు:',
  'priv.dont.i2d': 'మీరు ప్లాట్‌ఫారమ్‌ను ఎలా వాడతారో లేదా ఏ ఫీచర్లను యాక్సెస్ చేస్తారో మేము ట్రాక్ చేయము',
  'priv.dont.i3l': 'ట్రేడింగ్ డేటా లేదు:',
  'priv.dont.i3d': 'మీ స్ట్రాటజీలు, ట్రేడ్‌లు, ఆర్థిక సమాచారం పూర్తిగా ప్రైవేట్‌గానే ఉంటాయి',
  'priv.dont.i4l': 'అనలిటిక్స్ లేదు:',
  'priv.dont.i4d': 'Google Analytics లేదు, ట్రాకింగ్ పిక్సెల్స్ లేవు, థర్డ్-పార్టీ మానిటరింగ్ లేదు',
  'priv.dont.i5l': 'కుకీలు లేవు:',
  'priv.dont.i5d': 'మేము ట్రాకింగ్ కుకీలు గానీ, ట్రాకింగ్ కోసం ఎలాంటి బ్రౌజర్ స్టోరేజ్ గానీ వాడము',
  'priv.dont.i6l': 'సర్వర్ లాగ్‌లు లేవు:',
  'priv.dont.i6d': 'మీ యాక్టివిటీలు లేదా యాక్సెస్ ప్యాటర్న్‌ల లాగ్‌లను మేము నిర్వహించము',
  'priv.self.title': 'సెల్ఫ్-హోస్టెడ్ ఆర్కిటెక్చర్',
  'priv.self.intro': 'OpenAlgo మీ సొంత ఇన్‌ఫ్రాస్ట్రక్చర్‌పై సెల్ఫ్-హోస్ట్ చేసుకునేలా రూపొందించబడింది. దీని అర్థం:',
  'priv.self.i1': 'మొత్తం డేటా మీ పూర్తి నియంత్రణలో మీ సర్వర్లపైనే ఉంటుంది',
  'priv.self.i2': 'మా సర్వర్లే లేనందున, డేటా ఎప్పుడూ మా వద్దకు చేరదు',
  'priv.self.i3': 'మీ ట్రేడింగ్ ఇన్‌ఫ్రాస్ట్రక్చర్‌లోని ప్రతి అంశాన్ని మీరే సొంతం చేసుకుని, నియంత్రిస్తారు',
  'priv.self.i4': 'సంపూర్ణ ప్రైవసీ, డేటా సార్వభౌమత్వం',
  'priv.control.title': 'మీ డేటా, మీ నియంత్రణ',
  'priv.control.intro': 'మీరు OpenAlgo వాడేటప్పుడు:',
  'priv.control.i1': 'మీ API కీలు మీ బ్రౌజర్‌లో లేదా మీ సెల్ఫ్-హోస్టెడ్ ఇన్‌స్టాన్స్‌లో లోకల్‌గా నిల్వ ఉంటాయి',
  'priv.control.i2': 'ట్రేడింగ్ డేటా మీ ఇన్‌స్టాన్స్‌కు, మీ బ్రోకర్‌కు మధ్య నేరుగా కమ్యూనికేట్ అవుతుంది',
  'priv.control.i3': 'కాన్ఫిగరేషన్, ప్రిఫరెన్సులు మీ లోకల్ సెటప్‌లోనే ఉంటాయి',
  'priv.control.i4': 'మధ్యవర్తి సర్వర్లు గానీ, క్లౌడ్ సర్వీసులు గానీ ప్రమేయం ఉండవు',
  'priv.trans.title': 'పారదర్శకత',
  'priv.trans.intro': 'OpenAlgo AGPL-3.0 లైసెన్స్ కింద పూర్తిగా ఓపెన్ సోర్స్. మీరు వీటిని చేయవచ్చు:',
  'priv.trans.i1': 'GitHubలో మొత్తం కోడ్‌బేస్‌ను ఆడిట్ చేయవచ్చు',
  'priv.trans.i2': 'డేటా సేకరణ కోడ్ ఏదీ లేదని ధృవీకరించుకోవచ్చు',
  'priv.trans.i3': 'పూర్తి భరోసా కోసం సోర్స్ నుంచి బిల్డ్ చేసి డిప్లాయ్ చేసుకోవచ్చు',
  'priv.trans.i4': 'ప్రాజెక్ట్‌కు కంట్రిబ్యూట్ చేసి, ప్రైవసీ ప్రమాణాలను కాపాడేందుకు సాయపడవచ్చు',
  'priv.third.title': 'థర్డ్-పార్టీ సర్వీసులు',
  'priv.third.intro': 'ఈ వెబ్‌సైట్ (openalgo.in) వీటిని వాడవచ్చు:',
  'priv.third.i1': "CDN, DDoS ప్రొటెక్షన్ కోసం Cloudflare (Cloudflare ప్రైవసీ పాలసీ చూడండి)",
  'priv.third.i2': 'డాక్యుమెంటేషన్, సోర్స్ కోడ్ హోస్టింగ్ కోసం GitHub',
  'priv.third.note': 'గమనిక: OpenAlgo అప్లికేషన్ స్వయంగా, సెల్ఫ్-హోస్ట్ చేసినప్పుడు, ఎలాంటి థర్డ్-పార్టీ సర్వీసులను వాడదు.',
  'priv.changes.title': 'ఈ పాలసీలో మార్పులు',
  'priv.changes.body': 'సున్నా డేటా సేకరణకు మా నిబద్ధత శాశ్వతమైనది. ఈ పాలసీలో ఏ అప్‌డేట్లయినా మా ప్రైవసీ వైఖరిని స్పష్టం చేయడానికి లేదా బలోపేతం చేయడానికి మాత్రమే, ఎప్పుడూ బలహీనపరచడానికి కాదు.',
  'priv.contact.title': 'సంప్రదించండి',
  'priv.contact.intro': 'ఈ ప్రైవసీ పాలసీ గురించి లేదా OpenAlgo ప్రైవసీ పద్ధతుల గురించి ప్రశ్నల కోసం:',
  'priv.contact.discord': 'మా కమ్యూనిటీలో చేరండి',
  'priv.contact.email': 'ఇమెయిల్:',
  'priv.footer.title': 'ఎప్పుడూ ప్రైవసీకే ప్రాధాన్యం',
  'priv.footer.body': 'మీ ట్రేడింగ్ డేటా కేవలం మీదేనని OpenAlgo నమ్ముతుంది. ప్రైవసీ విషయంలో మేము ఎప్పుడూ రాజీ పడము.',

