  'skill.btTitle': "బ్యాక్‌టెస్టింగ్ స్కిల్స్",
  'skill.btDesc': "రియల్ గత డేటాపై ట్రేడింగ్ ఐడియాలను టెస్ట్ చేయండి. భారత, US, క్రిప్టో మార్కెట్ల కోసం ఫీజులు, టాక్సులు, స్లిప్పేజ్ ఇప్పటికే చేర్చబడ్డాయి - కాబట్టి ఫలితాలు మీ అకౌంట్‌లో నిజంగా మీరు చూసేదాన్నే ప్రతిబింబిస్తాయి.",
