  // MCP page
  'mcp.copy': "క్లిప్‌బోర్డ్‌కు కాపీ చేయండి",
  'mcp.hero.badge1': "ఓపెన్ సోర్స్",
  'mcp.hero.badge2': "Claude & ChatGPTతో పనిచేస్తుంది",
  'mcp.hero.badge3': "మీ కంప్యూటర్‌లో రన్ అవుతుంది",
  'mcp.hero.h1a': "కేవలం అడగడం ద్వారానే",
  'mcp.hero.h1b': "మీ AIతో ట్రేడ్ చేయండి",
  'mcp.hero.desc': "OpenAlgo MCP మీ AI చాట్ యాప్‌ను - Claude, Cursor, Windsurf, లేదా ChatGPT - మీ OpenAlgo ట్రేడింగ్ ఖాతాకు కలుపుతుంది. కేవలం మాట్లాడటం ద్వారానే ఆర్డర్లు పెట్టండి, పొజిషన్లు చూడండి, మరియు రియల్ ధరలు పొందండి.",
  'mcp.hero.sub': "డాష్‌బోర్డులు లేవు. క్లిక్ చేయడం లేదు. మీకు కావాల్సింది టైప్ చేయండి, మీ బ్రోకర్ ద్వారా మీ AI దాన్ని పూర్తి చేస్తుంది.",
  'mcp.hero.ctaQuickstart': "క్విక్‌స్టార్ట్",
  'mcp.hero.ctaGithub': "GitHubలో చూడండి",
  'mcp.hero.ctaDocs': "డాక్స్",
  'mcp.chat.title': "ఇది ఎలా అనిపిస్తుంది",
  'mcp.chat.sub': "ఇది ఒక ట్రేడర్ మరియు వారి AI మధ్య జరిగిన నిజమైన సంభాషణ. మీరు డాష్‌బోర్డ్‌ను ఎప్పుడూ తాకలేదని గమనించండి.",
  'mcp.chat.user': "బ్యాంకింగ్‌లో బలహీనత కనిపిస్తోంది. BANKNIFTY ఆప్షన్లలో నా MIS పొజిషన్లను స్క్వేర్ ఆఫ్ చేసి, P&L చూపించు.",
  'mcp.chat.ai1': "చేస్తున్నాను. ముందు మీ BANKNIFTY MIS పొజిషన్లను చూద్దాం...",
  'mcp.chat.ai2': "రెండింటినీ ఇప్పుడు క్లోజ్ చేస్తున్నాను...",
  'mcp.chat.done': "పూర్తయింది. ఈరోజు రియలైజ్డ్ P&L:",
  'mcp.chat.note': "ఇది ఉదాహరణ సంభాషణ. మీ AI వెతికి, అమలు చేస్తుంది - మీరు కేవలం ధృవీకరించి చూస్తారు.",
  'mcp.why.title': "ట్రేడర్లు దీన్ని ఎందుకు ఇష్టపడతారు",
  'mcp.why.sub': "ఏడు స్క్రీన్లు క్లిక్ చేసే బదులు, తమకు కావాల్సింది చెప్పాలనుకునే ట్రేడర్ల కోసం రూపొందించబడింది.",
  'mcp.cap1t': "మాట్లాడండి, క్లిక్ చేయకండి",
  'mcp.cap1d': "\"RELIANCE 100 షేర్లు మార్కెట్ ధరకు కొను.\" అంతే. ఫారాలు లేవు, మెనూలు లేవు - మీ AIకి ఏం చేయాలో చెప్పండి చాలు.",
  'mcp.cap2t': "ఒక సూచన, అనేక దశలు",
  'mcp.cap2d': "\"నా పొజిషన్లు చూసి, నష్టంలో ఉన్నవి క్లోజ్ చేయి\" అని చెప్పండి, మీ AI రెండూ ఒకేసారి చేస్తుంది.",
  'mcp.cap3t': "అవసరమైనప్పుడు రియల్ ధరలు",
  'mcp.cap3d': "కోట్లు, మార్కెట్ డెప్త్, లేదా హిస్టారికల్ చార్టుల కోసం మీ చాట్‌లోనే అడగండి. నిజమైన నంబర్లు, నిజమైన సమయంలో.",
  'mcp.cap4t': "మీ డేటా మీ దగ్గరే ఉంటుంది",
  'mcp.cap4d': "ప్రతిదీ మీ సొంత కంప్యూటర్‌లోనే రన్ అవుతుంది. మీ API కీ మరియు ట్రేడ్‌లు మీ మెషిన్ నుండి ఎప్పుడూ బయటకు వెళ్ళవు.",
  'mcp.cap5t': "అదే చాట్, ఏ బ్రోకర్ అయినా",
  'mcp.cap5d': "OpenAlgo సపోర్ట్ చేసే ప్రతి బ్రోకర్‌తో పనిచేస్తుంది. కొత్తగా ఏమీ నేర్చుకోకుండానే బ్రోకర్లను మార్చండి.",
  'mcp.cap6t': "40+ బిల్ట్-ఇన్ యాక్షన్లు",
  'mcp.cap6d': "ఆర్డర్లు పెట్టండి, ఆప్షన్లు ట్రేడ్ చేయండి, ఫండ్స్ చూడండి, గ్రీక్స్ పొందండి, సింబల్స్ వెతకండి - మీ AIకి ఇది ఇప్పటికే తెలుసు.",
  'mcp.how.title': "ఇది ఎలా పనిచేస్తుంది",
  'mcp.how.sub': "మీరు మాట్లాడతారు, మీ AI చర్య తీసుకుంటుంది, OpenAlgo దాన్ని రన్ చేస్తుంది, మీ బ్రోకర్ అమలు చేస్తుంది. నాలుగు దశలు - మీరు మొదటిది మాత్రమే చూసుకోవాలి.",
  'mcp.how.step': "దశ {n}",
  'mcp.flow1t': "మీరు అడుగుతారు",
  'mcp.flow1d': "\"నా ఓపెన్ పొజిషన్లు చూపించి, నష్టంలో ఉన్నవి క్లోజ్ చేయి.\"",
  'mcp.flow2t': "AI అర్థం చేసుకుంటుంది",
  'mcp.flow2d': "Claude, Cursor, Windsurf, లేదా ChatGPT మీకు ఏం కావాలో గుర్తిస్తుంది.",
  'mcp.flow3t': "OpenAlgo చర్య తీసుకుంటుంది",
  'mcp.flow3d': "మీ కంప్యూటర్‌లో రన్ అవుతున్న మీ OpenAlgo ఈ రిక్వెస్ట్‌ను హ్యాండిల్ చేస్తుంది.",
  'mcp.flow4t': "బ్రోకర్ అమలు చేస్తుంది",
  'mcp.flow4d': "ఆర్డర్ మీ బ్రోకర్‌కు వెళ్లి, ఎక్స్ఛేంజ్‌ను చేరుకుంటుంది - ఎప్పటిలాగే.",
  'mcp.prompts.title': "మీరు కేవలం అడగగలిగే విషయాలు",
  'mcp.prompts.sub': "మీరు సెటప్ చేసిన తర్వాత వీటిలో ఏదైనా వెంటనే పనిచేస్తుంది. ప్రత్యేక పదజాలం అవసరం లేదు - సహజంగా మాట్లాడండి.",
  'mcp.prompt1': "మార్కెట్ ధరకు RELIANCE 100 షేర్ల కొనుగోలు ఆర్డర్ పెట్టు",
  'mcp.prompt2': "నా ప్రస్తుత పొజిషన్లు మరియు ఈరోజు P&L చూపించు",
  'mcp.prompt3': "NIFTYకి తాజా కోట్ ఏమిటి?",
