  'mcp.prompt6': "గత ట్రేడింగ్ రోజుకు BANKNIFTY కోసం 5-నిమిషాల హిస్టారికల్ డేటా తీసుకురా",
  'mcp.prompt7': "ఈ గురువారం ముగిసే అన్ని వీక్లీ NIFTY ఆప్షన్లను వెతుకు",
  'mcp.prompt8': "మధ్యాహ్నం 3:15కి ముందు నా MIS పొజిషన్లన్నీ క్లోజ్ చేయి",
  'mcp.tools.title': "మీరు చేయగలిగినవన్నీ",
  'mcp.tools.sub': "OpenAlgo చేయగలిగినది ఏదైనా, ఇప్పుడు మీ AI మీ కోసం చేయగలదు. ట్రేడర్లు నిజంగా ఆలోచించే విధంగా గ్రూప్ చేయబడింది.",
  'mcp.tg1.title': "ఆర్డర్లు పెట్టడం & నిర్వహించడం",
