  'mcp.tg2.i2l': "మల్టీ-లెగ్ స్ట్రాటజీలు",
  'mcp.tg2.i2d': "ఐరన్ కండార్లు, స్ప్రెడ్లు, బటర్‌ఫ్లైలు, స్ట్రాడిల్స్ - అన్నీ ఒకే రిక్వెస్ట్‌లో",
