  'mcp.qs1.b3': "GitHub నుండి MCP సెటప్ ఫైళ్లను డౌన్‌లోడ్ చేయండి. పూర్తి సెటప్ గైడ్ దీన్ని ఒక నిమిషం లోపు వివరిస్తుంది.",
