  'mcp.qs2.title': "OpenAlgo గురించి మీ AIకి చెప్పండి",
  'mcp.qs2.desc': "కింద మీ ఆపరేటింగ్ సిస్టమ్‌ను ఎంచుకుని, సెట్టింగ్‌లను కాపీ చేసి, మీ AI యాప్ కాన్ఫిగ్ ఫైల్‌లో పేస్ట్ చేయండి. పాత్‌లు మరియు API కీని మీ సొంతవాటితో మార్చండి.",
