  'mcp.qs3.desc': "Claude Desktop, Cursor, లేదా Windsurfను మూసి తిరిగి తెరవండి. OpenAlgo స్వయంచాలకంగా కనెక్ట్ అవుతుంది. ముందు ఏదైనా సాధారణమైనది అడిగి చూడండి:",
