  'mcp.exch.sub': "OpenAlgo ద్వారా మీ బ్రోకర్ మిమ్మల్ని ట్రేడ్ చేయనిచ్చేది ఏదైనా, మీరు చాట్ ద్వారా ట్రేడ్ చేయవచ్చు.",
