  'mcp.sec.b1': "ప్రతిదీ మీ సొంత కంప్యూటర్‌లోనే రన్ అవుతుంది. మీ ఆర్డర్లు మరియు ఖాతా సమాచారం మీ మెషిన్ నుండి ఎప్పుడూ బయటకు వెళ్ళవు.",
