  // WABridge page
  'wab.badgeOpenSource': "ఓపెన్ సోర్స్",
  'wab.heroTag': "ఒక తేలికైన WhatsApp HTTP బ్రిడ్జ్.",
  'wab.heroDesc': "CLI ద్వారా మీ WhatsAppను లింక్ చేసి, ఒక సాధారణ REST APIద్వారా మెసేజీలు పంపండి. టెక్స్ట్, ఇమేజీలు, వీడియో, ఆడియో, డాక్యుమెంట్లకు మద్దతు ఇస్తుంది - వ్యక్తులకు, గ్రూపులకు, మరియు ఛానెల్‌లకు.",
  'wab.orRun': "లేదా నేరుగా రన్ చేయండి:",
  'wab.ctaNode': "Node.js CLI",
  'wab.ctaPython': "Python SDK",
  'wab.howTitle': "ఇది ఎలా పనిచేస్తుంది",
  'wab.howDesc': "WABridge మీ అప్లికేషన్లు మరియు WhatsApp మధ్య కూర్చుని, ఒక లోకల్ HTTP సర్వర్ ద్వారా మెసేజీలను రూట్ చేస్తుంది.",
  'wab.howCaption': "మీ యాప్ WABridgeకి HTTP రిక్వెస్టులు పంపుతుంది, అది వాటిని WhatsAppకి డెలివర్ చేస్తుంది.",
  'wab.f1t': "సింపుల్ REST API",
  'wab.f1d': "మెసేజ్ పంపడానికి ఒకే POST రిక్వెస్ట్. సంక్లిష్టమైన SDKలు లేదా auth ఫ్లోలు అవసరం లేదు.",
  'wab.f2t': "రిచ్ మీడియా",
  'wab.f2d': "ఇమేజీలు, వీడియోలు, వాయిస్ నోట్‌లు, మరియు డాక్యుమెంట్లు పంపండి. URLలు మరియు లోకల్ ఫైల్ పాత్‌లకు మద్దతు ఇస్తుంది.",
  'wab.f3t': "గ్రూపులు & ఛానెల్‌లు",
  'wab.f3d': "వ్యక్తులకు, గ్రూపులకు, మరియు ఛానెల్‌లకు పంపండి. వాటి JIDలతో సహా గ్రూపులను ప్రోగ్రామాటిక్‌గా లిస్ట్ చేయండి.",
  'wab.f4t': "సెల్ఫ్-హోస్టెడ్",
  'wab.f4d': "మీ మెషిన్‌లోనే రన్ అవుతుంది. థర్డ్-పార్టీ క్లౌడ్ సర్వీసులు లేవు. మీ మెసేజీలు లోకల్‌గానే ఉంటాయి.",
  'wab.f5t': "Python SDK",
  'wab.f5d': "ఒక ఫంక్షన్ కాల్‌తో Pythonతో నుండి మెసేజీలు పంపండి. సింక్ మరియు async సపోర్ట్ బిల్ట్-ఇన్‌గా ఉన్నాయి.",
  'wab.f6t': "ఇంటరాక్టివ్ CLI",
  'wab.f6d': "టెర్మినల్ నుండి ఇంటరాక్టివ్‌గా మెసేజీలను టెస్ట్ చేయండి. QR కోడ్ లేదా పెయిరింగ్ కోడ్ ద్వారా లింక్ చేయండి.",
  'wab.qsTitle': "క్విక్ స్టార్ట్",
  'wab.qs1t': "WhatsApp లింక్ చేయండి",
  'wab.qs1qr': "QR కోడ్ (డిఫాల్ట్):",
