  'sip.srv.sharedBest': "టెస్టింగ్, చిన్న క్యాపిటల్",
  'sip.srv.dedTitle': "డెడికేటెడ్ CPU",
  'sip.srv.dedDesc': "మీ స్వంత ప్రైవేట్ విల్లా లాంటిది. వనరులు పూర్తిగా మీవే. వేగవంతమైన మరియు మరింత స్థిరమైన పనితీరు.",
  'sip.srv.dedLatency': "30 నుండి 120ms",
