  'sip.srv.dedBest': "లైవ్ ట్రేడింగ్, పెద్ద క్యాపిటల్",
  'sip.srv.vpsTitle': "VPS ప్రొవైడర్లు",
  'sip.srv.vultrNote': "గంటవారీ బిల్లింగ్, ముంబై డేటాసెంటర్ అందుబాటులో ఉంది",
  'sip.srv.doNote': "డ్రాప్‌లెట్‌లు, మంచి డాక్యుమెంటేషన్",
  'sip.srv.contaboNote': "చాలా చౌక, షేర్డ్ CPU",
