  'sip.cost.r6C': "ఎప్పటికీ ఉచితం",
  'sip.cost.r6N': "ఓపెన్ సోర్స్ (AGPL-3.0)",
  'sip.cost.totTitle': "మొత్తం అంచనా ఖర్చు:",
  'sip.cost.totA': "సుమారుగా దీని నుండి మొదలవుతుంది",
  'sip.cost.totB': "నెలకు ₹1,500 నుండి ₹2,000",
  'sip.cost.totC': "డొమైన్ + VPSతో బేసిక్ సెటప్ కోసం. OpenAlgo, Cloudflare, మరియు SSL అన్నీ ఉచితం.",
  'sip.cta.title': "డిప్లాయ్ చేయడానికి సిద్ధంగా ఉన్నారా?",
  'sip.cta.sub': "వివరణాత్మక ఇన్‌స్టాలేషన్ సూచనల కోసం డాక్యుమెంటేషన్‌ను అనుసరించండి.",
